package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_constructSettableProperty_TriageGen1Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanPropertyDefinition propDef;
    private JavaType propType;
    private TypeFactory typeFactory;

    // Test target class
    public static class TestBean {
        public String name;
        @JsonProperty("age")
        public int age;

        public void setName(String name) {}
        public void setAge(int age) {}
    }

    @Before
    public void setUp() {
        factory = new BeanDeserializerFactory(DeserializerFactoryConfig.NO_CONFIG);
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        propDef = mock(BeanPropertyDefinition.class);
        propType = mock(JavaType.class);
        typeFactory = TypeFactory.defaultInstance();

        // Default mock behaviors to avoid NPEs in the method logic
        when(beanDesc.getClassAnnotations()).thenReturn(AnnotationIntrospector.noop());
        when(propType.getTypeHandler()).thenReturn(null);
        when(propType.getValueHandler()).thenReturn(null);
    }

    /**
     * Helper to invoke the protected method via reflection
     */
    @SuppressWarnings("unchecked")
    private SettableBeanProperty invokeConstructSettableProperty(DeserializationContext ctxt,
                                                                BeanDescription beanDesc,
                                                                BeanPropertyDefinition propDef,
                                                                JavaType propType) throws Exception {
        java.lang.reflect.Method method = BeanDeserializerFactory.class.getDeclaredMethod(
                "constructSettableProperty", DeserializationContext.class, BeanDescription.class, 
                BeanPropertyDefinition.class, JavaType.class);
        method.setAccessible(true);
        return (SettableBeanProperty) method.invoke(factory, ctxt, beanDesc, propDef, propType);
    }

    @Test(expected = Exception.class)
    public void testConstructSettableProperty_NoMutatorThrowsException() throws Exception {
        when(propDef.getNonConstructorMutator()).thenReturn(null);
        // The method calls ctxt.reportBadPropertyDefinition which usually throws JsonMappingException
        doThrow(new JsonMappingException(null, "No non-constructor mutator available"))
                .when(ctxt).reportBadPropertyDefinition(any(), any(), anyString());

        invokeConstructSettableProperty(ctxt, beanDesc, propDef, propType);
    }

    @Test
    public void testConstructSettableProperty_MethodProperty() throws Exception {
        // Setup a Method mutator
        Method setter = TestBean.class.getMethod("setName", String.class);
        AnnotatedMethod annotatedMethod = mock(AnnotatedMethod.class);
        when(annotatedMethod.getMember()).thenReturn(setter);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedMethod);

        // Mock type resolution (since we can't easily mock the internal resolveMemberAndTypeAnnotations)
        // We use a real JavaType to avoid complex deep mocking of the resolution logic
        JavaType realType = typeFactory.constructType(String.class);
        when(propType.getTypeHandler()).thenReturn(null);

        // We need to spy the factory to handle the internal protected method calls if necessary, 
        // but here we are testing the actual implementation.
        // Since resolveMemberAndTypeAnnotations is protected and called internally, 
        // we ensure the mock setup is sufficient or use a subclass.

        BeanDeserializerFactory spyFactory = spy(factory);
        // We can't easily mock resolveMemberAndTypeAnnotations without a subclass
        // So we rely on the fact that it's part of the same class.

        SettableBeanProperty prop = invokeConstructSettableProperty(ctxt, beanDesc, propDef, realType);

        assertNotNull(prop);
        assertTrue(prop instanceof MethodProperty);
    }

    @Test
    public void testConstructSettableProperty_FieldProperty() throws Exception {
        // Setup a Field mutator
        Field field = TestBean.class.getDeclaredField("age");
        AnnotatedField annotatedField = mock(AnnotatedField.class);
        when(annotatedField.getMember()).thenReturn(field);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedField);

        JavaType realType = typeFactory.constructType(int.class);

        SettableBeanProperty prop = invokeConstructSettableProperty(ctxt, beanDesc, propDef, realType);

        assertNotNull(prop);
        assertTrue(prop instanceof FieldProperty);
    }

    @Test
    public void testConstructSettableProperty_WithDeserializerAndContextualization() throws Exception {
        Method setter = TestBean.class.getMethod("setName", String.class);
        AnnotatedMethod annotatedMethod = mock(AnnotatedMethod.class);
        when(annotatedMethod.getMember()).thenReturn(setter);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedMethod);

        JavaType realType = typeFactory.constructType(String.class);
        JsonDeserializer<?> mockDeser = mock(JsonDeserializer.class);

        // Mock findDeserializerFromAnnotation via a spy or by ensuring the logic flows
        // Since findDeserializerFromAnnotation is protected, we mock the behavior via ctxt or type
        when(realType.getValueHandler()).thenReturn(mockDeser);

        // Mock context handler
        when(ctxt.handlePrimaryContextualization(eq(mockDeser), any(), eq(realType))).thenReturn(mockDeser);

        // To test findDeserializerFromAnnotation, we need to ensure it returns null so it falls back to valueHandler
        // We'll use a spy to override findDeserializerFromAnnotation
        BeanDeserializerFactory spyFactory = spy(new BeanDeserializerFactory(DeserializerFactoryConfig.NO_CONFIG));
        doReturn(null).when(spyFactory).findDeserializerFromAnnotation(any(), any());

        // Because we are testing the method directly via reflection on the spy:
        java.lang.reflect.Method method = BeanDeserializerFactory.class.getDeclaredMethod(
                "constructSettableProperty", DeserializationContext.class, BeanDescription.class, 
                BeanPropertyDefinition.class, JavaType.class);
        method.setAccessible(true);

        SettableBeanProperty prop = (SettableBeanProperty) method.invoke(spyFactory, ctxt, beanDesc, propDef, realType);

        assertNotNull(prop);
        verify(ctxt).handlePrimaryContextualization(eq(mockDeser), any(), eq(realType));
    }

    @Test
    public void testConstructSettableProperty_WithReferenceAndObjectId() throws Exception {
        Method setter = TestBean.class.getMethod("setName", String.class);
        AnnotatedMethod annotatedMethod = mock(AnnotatedMethod.class);
        when(annotatedMethod.getMember()).thenReturn(setter);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedMethod);

        JavaType realType = typeFactory.constructType(String.class);

        // Mock Reference
        AnnotationIntrospector.ReferenceProperty ref = mock(AnnotationIntrospector.ReferenceProperty.class);
        when(ref.isManagedReference()).thenReturn(true);
        when(ref.getName()).thenReturn("myRef");
        when(propDef.findReferenceType()).thenReturn(ref);

        // Mock ObjectIdInfo
        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(propDef.findObjectIdInfo()).thenReturn(objectIdInfo);

        SettableBeanProperty prop = invokeConstructSettableProperty(ctxt, beanDesc, propDef, realType);

        assertNotNull(prop);
        assertEquals("myRef", prop.getManagedReferenceName());
        assertEquals(objectIdInfo, prop.getObjectIdInfo());
    }
}
